// On Linux, set via: export MY_FLAG=""
// .NET 9 breaking change: GetEnvironmentVariable now returns null for
// empty env vars on Unix. Use string.IsNullOrEmpty to preserve behavior,
// or check existence explicitly via /proc/self/environ or env command.
var val = Environment.GetEnvironmentVariable("MY_FLAG");
if (val is null && !EnvironmentVariableExists("MY_FLAG"))
{
    Console.WriteLine("MY_FLAG not set, using default");
}

using System.Runtime.InteropServices;

class EnvVarCheck
{
    // .NET 9 returns null for empty env vars on Unix (previously returned "").
    // Use P/Invoke to distinguish "not set" from "set but empty".
    [DllImport("libc", EntryPoint = "getenv", CharSet = CharSet.Ansi)]
    private static extern IntPtr NativeGetEnv(string name);

    static bool EnvironmentVariableExists(string name)
    {
        if (!RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
            return Environment.GetEnvironmentVariable(name) != null;
        return NativeGetEnv(name) != IntPtr.Zero;
    }

